Este es tu laboratorio **Infix a postfix** en Python. Pásalo a **pseudocódigo**, con las dos funciones y un stack:

```python
def jer(s):
    if s == "^":
        return 3
    elif s == "*" or s == "/":
        return 2
    elif s == "+" or s == "-":
        return 1
    return 0

def convertir(expresion):
    signos = []
    postfix = ""
    for c in expresion:
        if c in "+-*/^":
            while len(signos) > 0 and jer(signos[-1]) >= jer(c):
                postfix = postfix + signos.pop()
            signos.append(c)
        elif c == "(":
            signos.append(c)
        elif c == ")":
            while signos[-1] != "(":
                postfix = postfix + signos.pop()
            signos.pop()
        else:
            postfix = postfix + c
    while len(signos) > 0:
        postfix = postfix + signos.pop()
    return postfix

print(convertir(input()))
```

